From ddd2dc968d03508041746dd5e681a659cfd9812f Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 10:38:41 +0100
Subject: [PATCH] klipper: only keep the original image format and none of its
 exports

Apps like Inkscape offer a copied object in many formats and Klipper
read all of them, making the app export it to EMF, WMF, LaTeX and more
on every copy. Now only the first image format, PNG and text are kept.

BUG: 504469
---
 klipper/updateclipboardjob.cpp | 12 ++++++++++++
 1 file changed, 12 insertions(+)

diff --git a/klipper/updateclipboardjob.cpp b/klipper/updateclipboardjob.cpp
index 8deecfe676..d85bb142dc 100644
--- a/klipper/updateclipboardjob.cpp
+++ b/klipper/updateclipboardjob.cpp
@@ -68,6 +68,7 @@ UpdateDatabaseJob *UpdateDatabaseJob::updateClipboard(QObject *parent,
     bool isUriListSet = false;
     bool isPlainTextSet = false;
     bool isPngSet = false;
+    bool isOriginalImageSet = false;
     const bool usePng = pngIt != end;
     for (auto it = begin; it != end; ++it) {
         const auto &format = *it;
@@ -124,6 +125,12 @@ UpdateDatabaseJob *UpdateDatabaseJob::updateClipboard(QObject *parent,
             }
             const bool isPngOrQtImage = it == pngIt || it == qtImageIt;
             if (!isPngOrQtImage) {
+                // Apps like Inkscape offer many exports of the copied object;
+                // only keep the first one, which is the original.
+                if (isOriginalImageSet) {
+                    continue;
+                }
+                isOriginalImageSet = true;
                 const auto data = mimeData->data(format);
                 hash.reset();
                 hash.addData(data);
@@ -157,6 +164,11 @@ UpdateDatabaseJob *UpdateDatabaseJob::updateClipboard(QObject *parent,
             continue;
         }

+        // Text formats offered after the original image are exports of it.
+        if (isOriginalImageSet && it != suggestedFilenameIt) {
+            continue;
+        }
+
         QByteArray data = mimeData->data(format);
         if (data.size() > 20 * 1000 * 1000) {
             // Skip anything greater than 20MB because we don't want too
